/bin/bash -lc "python - <<'PY'
import json
x=json.load(open('run_trace/galaxy_tool_run/validation_response.json'))

def rec(obj, d=0):
    if isinstance(obj,dict):
        mc=obj.get('model_class')
        if mc in ('Conditional','ConditionalWhen','SelectToolParameter'):
            print('  '*d, mc, 'name=',obj.get('name'),'value=',obj.get('value'),'test_param=', (obj.get('test_param') or {}).get('name'))
        for k,v in obj.items():
            if k in ('options','help'): continue
            rec(v,d+1)
    elif isinstance(obj,list):
        for v in obj: rec(v,d)
rec(x['inputs'])
PY"
